/**
 * Mars Survival Hub — proof-of-concept dashboard.
 *
 * The cards, layout and two tools ("route to nearest waypoint" and the offline
 * waypoint export) work. The emergency PROCEDURES are deliberately empty
 * placeholders: they must be written and verified by qualified mission safety
 * specialists, not generated by the app.
 */
import { useEffect, useState, type ReactNode } from 'react';
import { api } from '../lib/api';
import { fmtDistance, fmtLat, fmtLon } from '../lib/format';
import type { MapPoint, Waypoint } from '../lib/types';
import { useStore } from '../store/useStore';
import { Modal } from './Dialogs';
import { IAntenna, ICloud, IDownload, IHeartPulse, IMap, IPin, IRoute, IShieldAlert, IShieldPlus, IWind } from './icons';
import { Button, Notice } from './ui';

type ScenarioId = 'oxygen' | 'dust' | 'lost' | 'suit' | 'injury' | 'comms';

interface Scenario {
  id: ScenarioId;
  title: string;
  subtitle: string;
  icon: ReactNode;
  tint: string;          // text colour class for the icon
  appData: string[];     // what this app can genuinely contribute
}

const SCENARIOS: Scenario[] = [
  { id: 'oxygen', title: 'Oxygen Emergency', subtitle: 'Life-support response', icon: <IWind width={20} height={20} />, tint: 'text-rose',
    appData: ['Distances and terrain-cost routes to saved waypoints (e.g. a habitat or rover)'] },
  { id: 'dust', title: 'Dust Storm', subtitle: 'Weather protection', icon: <ICloud width={20} height={20} />, tint: 'text-caution',
    appData: ['Saved shelter waypoints and routes to them', 'No atmospheric or weather data is integrated in this prototype'] },
  { id: 'lost', title: 'Lost or Stranded', subtitle: 'Navigation assistance', icon: <IPin width={20} height={20} />, tint: 'text-sky',
    appData: ['Martian coordinates of any point', 'Nearest saved waypoint', 'Terrain-aware A* route estimate'] },
  { id: 'suit', title: 'Suit Malfunction', subtitle: 'Suit safety procedures', icon: <IShieldAlert width={20} height={20} />, tint: 'text-alert',
    appData: ['Route back to a saved waypoint; suit telemetry is not part of this prototype'] },
  { id: 'injury', title: 'Injury or Fall', subtitle: 'Medical response', icon: <IHeartPulse width={20} height={20} />, tint: 'text-violet',
    appData: ['Slope at the location (falls on steep terrain)', 'Location to report to the support team'] },
  { id: 'comms', title: 'Communication Loss', subtitle: 'Offline operations', icon: <IAntenna width={20} height={20} />, tint: 'text-mint',
    appData: ['Offline copy of all waypoints (download below)'] },
];

function nearest(p: MapPoint, wps: Waypoint[]): { wp: Waypoint; d: number } | null {
  let best: { wp: Waypoint; d: number } | null = null;
  for (const wp of wps) {
    const d = Math.hypot(wp.x - p.x, wp.y - p.y);
    if (!best || d < best.d) best = { wp, d };
  }
  return best;
}

function downloadWaypoints(wps: Waypoint[], crsId: string) {
  const fc = {
    type: 'FeatureCollection',
    name: 'jezero-waypoints',
    // NOTE: Mars coordinates (planetocentric, east-positive), not Earth WGS84.
    crs: { type: 'name', properties: { name: 'Mars 2000 sphere, planetocentric lat / east-positive lon (degrees)', project_crs: crsId } },
    features: wps.map((w) => ({
      type: 'Feature',
      geometry: { type: 'Point', coordinates: [w.lon_e, w.lat] },
      properties: { id: w.id, name: w.name, description: w.description, x_m: w.x, y_m: w.y, crs_id: w.crs_id, crs_version: w.crs_version, updated_at: w.updated_at },
    })),
  };
  const blob = new Blob([JSON.stringify(fc, null, 2)], { type: 'application/geo+json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `jezero-waypoints-${new Date().toISOString().slice(0, 10)}.geojson`;
  a.click();
  URL.revokeObjectURL(url);
}

function ScenarioTools({ s, close }: { s: Scenario; close: () => void }) {
  const waypoints = useStore((s2) => s2.waypoints);
  const inspectPoint = useStore((s2) => s2.inspectPoint);
  const routeStart = useStore((s2) => s2.route.start);
  const setRoutePoint = useStore((s2) => s2.setRoutePoint);
  const compute = useStore((s2) => s2.computeRoute);
  const setView = useStore((s2) => s2.setView);
  const setMode = useStore((s2) => s2.setMode);
  const config = useStore((s2) => s2.config);
  const position = inspectPoint ?? routeStart;

  if (s.id === 'lost' || s.id === 'oxygen' || s.id === 'dust' || s.id === 'suit') {
    const near = position ? nearest(position, waypoints) : null;
    return (
      <div className="space-y-3">
        {!position && <Notice>Mark your position first: open the map and click where you are (Inspect tool).</Notice>}
        {position && waypoints.length === 0 && <Notice>No saved waypoints yet. Add a waypoint for your habitat, rover or shelter.</Notice>}
        {near && (
          <Notice tone="info">
            Nearest waypoint: <b className="text-ink">{near.wp.name}</b> · {fmtDistance(near.d)} straight-line
          </Notice>
        )}
        <div className="flex flex-wrap gap-2">
          <Button
            variant="primary"
            disabled={!position || !near}
            onClick={() => {
              if (!position || !near) return;
              setRoutePoint('start', position, 'My position');
              setRoutePoint('end', { x: near.wp.x, y: near.wp.y }, near.wp.name);
              setView('map');
              close();
              void compute();
            }}
          >
            <IRoute /> Route to nearest waypoint
          </Button>
          <Button onClick={() => { setView('map'); setMode('inspect'); close(); }}><IMap /> {position ? 'Change position' : 'Mark position on map'}</Button>
        </div>
      </div>
    );
  }
  if (s.id === 'comms') {
    return (
      <div className="space-y-3">
        <Button variant="primary" disabled={waypoints.length === 0 || !config} onClick={() => config && downloadWaypoints(waypoints, config.crs.id)}>
          <IDownload /> Download {waypoints.length} waypoint{waypoints.length === 1 ? '' : 's'} (GeoJSON)
        </Button>
      </div>
    );
  }
  return (
    <div className="space-y-3">
      {position && config && (
        <Notice>Marked location ready to share. Open the map’s Point tab for its coordinates and slope.</Notice>
      )}
      <Button onClick={() => { setView('map'); close(); }}><IMap /> Open map</Button>
    </div>
  );
}

function ScenarioDialog({ s, onClose }: { s: Scenario; onClose: () => void }) {
  return (
    <Modal title={s.title} onClose={onClose}>
      <div className="space-y-4">
        <div className="flex items-center gap-3">
          <span className={s.tint}>{s.icon}</span>
          <span className="text-xs text-dim">{s.subtitle}</span>
          <span className="ml-auto rounded-full bg-caution/10 px-2 py-0.5 text-[10px] font-medium text-caution">Concept</span>
        </div>
        {['Immediate actions', 'Communicate', 'Recover & report'].map((h) => (
          <section key={h}>
            <div className="mb-1 text-xs font-semibold text-ink">{h}</div>
            <div className="rounded-xl border border-dashed border-rim2 px-3 py-2.5 text-[11px] text-faint">
              To be written by mission safety specialists.
            </div>
          </section>
        ))}
        <section>
          <div className="mb-1 text-xs font-semibold text-ink">What this app can provide</div>
          <ul className="list-disc space-y-0.5 pl-4 text-xs text-dim">
            {s.appData.map((d) => <li key={d}>{d}</li>)}
          </ul>
        </section>
        <ScenarioTools s={s} close={onClose} />
      </div>
    </Modal>
  );
}

function Stat({ label, value, tone = 'text-ink' }: { label: string; value: ReactNode; tone?: string }) {
  return (
    <div className="rounded-xl bg-card px-4 py-3">
      <div className="text-[11px] text-faint">{label}</div>
      <div className={`mt-0.5 text-sm font-semibold ${tone}`}>{value}</div>
    </div>
  );
}

export default function SurvivalHub() {
  const config = useStore((s) => s.config);
  const waypoints = useStore((s) => s.waypoints);
  const inspectPoint = useStore((s) => s.inspectPoint);
  const inspect = useStore((s) => s.inspect);
  const [open, setOpen] = useState<Scenario | null>(null);
  const [apiOk, setApiOk] = useState<boolean | null>(null);
  const [latestSol, setLatestSol] = useState<number | null | undefined>(undefined);

  useEffect(() => {
    api.health().then(() => setApiOk(true)).catch(() => setApiOk(false));
    api.rawImages({ page: 0, per_page: 1, order: 'desc' })
      .then((p) => setLatestSol(p.images[0]?.sol ?? null))
      .catch(() => setLatestSol(null));
  }, []);

  const loc = inspect?.location && inspectPoint ? inspect.location : null;

  return (
    <div className="h-full overflow-y-auto">
      <div className="mx-auto max-w-3xl space-y-4 p-5 md:p-8">
        <div className="rounded-2xl bg-panel p-5 shadow-soft">
          <div className="flex items-center gap-3">
            <IShieldPlus className="text-mint" width={22} height={22} />
            <h1 className="text-lg font-medium text-ink">Survival hub</h1>
            <span className="ml-auto text-[11px] text-faint">Concept</span>
          </div>

          <div className="mt-4 grid grid-cols-1 gap-3 sm:grid-cols-2">
            {SCENARIOS.map((s) => (
              <button key={s.id} onClick={() => setOpen(s)}
                className="animate-fadein rounded-xl bg-card p-4 text-left shadow-soft transition-all hover:-translate-y-0.5 hover:bg-rim focus:outline-none focus-visible:ring-2 focus-visible:ring-signal/50">
                <span className={s.tint}>{s.icon}</span>
                <div className="mt-2 text-[15px] font-semibold text-ink">{s.title}</div>
                <div className="mt-1 text-xs text-dim">{s.subtitle}</div>
              </button>
            ))}
          </div>

        </div>

        <div className="grid grid-cols-2 gap-3 md:grid-cols-4">
          <Stat label="API link" value={apiOk === null ? 'Checking…' : apiOk ? 'Online' : 'Offline'} tone={apiOk === false ? 'text-alert' : apiOk ? 'text-mint' : 'text-dim'} />
          <Stat label="Saved waypoints" value={waypoints.length} />
          <Stat label="Map layers" value={config ? config.layers.length : '—'} />
          <Stat label="Latest raw image" value={latestSol === undefined ? 'Checking…' : latestSol === null ? 'Unavailable' : `Sol ${latestSol}`} />
        </div>

        <div className="rounded-xl bg-card px-4 py-3 text-xs text-dim">
          {loc ? (
            <>Marked position: <span className="font-mono text-ink">{fmtLat(loc.lat)} · {fmtLon(loc.lon_e)}</span></>
          ) : (
            <>No position marked.</>
          )}
        </div>
      </div>
      {open && <ScenarioDialog s={open} onClose={() => setOpen(null)} />}
    </div>
  );
}
